import sys; sys.path.insert(0,'superopt')
import so
so.build_core()
for n,tl in [('split100_leanest',180.0),('digits2x2_core',420.0)]:
    s=so.SPECS[n](); s['time_limit']=tl
    c=so.search_parallel(s,nproc=7)
    print('==',n,'->',len(c),'候选',flush=True)
    for x in c[:3]: print('   ',x.get('exprs'),'insns',x.get('insns'),'cyc',x.get('cyc'),flush=True)
